#!/usr/bin/env python3
"""A node's signal rating (protocol.md §16.1, ADR-0049).

An independent oracle, written from the spec in decibels: the demodulation limits are the
datasheet's table (Semtech SX1261/2, Table 6-1), not a formula; nothing is shared with the Rust
code, which works in quarter decibels. Each vector is a reading as the radio reports it
(`snr4`: SNR x 4; `rssi`: dBm, 0 when the radio does not measure it) under a preset's
spreading factor, and its rating. Regenerate with:
    python3 -I testdata/lichen/signal.py > testdata/lichen/signal.toml
"""

# LoRa demodulator SNR limit per spreading factor, dB (SX1261/2 datasheet, Table 6-1).
LIMIT_DB = {5: -2.5, 6: -5.0, 7: -7.5, 8: -10.0, 9: -12.5, 10: -15.0, 11: -17.5, 12: -20.0}

GOOD_MARGIN_DB = 10.0
FAIR_MARGIN_DB = 5.0
GOOD_RSSI_DBM = -115
FAIR_RSSI_DBM = -126

ORDER = ["Bad", "Fair", "Good"]


def by_snr(sf, snr_db):
    margin = snr_db - LIMIT_DB[sf]
    if margin >= GOOD_MARGIN_DB:
        return "Good"
    if margin >= FAIR_MARGIN_DB:
        return "Fair"
    return "Bad"


def by_rssi(rssi):
    if rssi >= GOOD_RSSI_DBM:
        return "Good"
    if rssi >= FAIR_RSSI_DBM:
        return "Fair"
    return "Bad"


def rating(sf, snr4, rssi):
    r = by_snr(sf, snr4 / 4)
    if rssi != 0:
        r = min(r, by_rssi(rssi), key=ORDER.index)
    return r


def vectors():
    out = []
    # Each spreading factor around its limit: at it, just under each margin, at each margin.
    for sf, limit in LIMIT_DB.items():
        for name, snr_db in [
            ("below the limit", limit - 2.0),
            ("at the limit", limit),
            ("just under fair", limit + FAIR_MARGIN_DB - 0.25),
            ("at fair", limit + FAIR_MARGIN_DB),
            ("just under good", limit + GOOD_MARGIN_DB - 0.25),
            ("at good", limit + GOOD_MARGIN_DB),
            ("strong", 12.0),
        ]:
            snr4 = round(snr_db * 4)
            out.append((f"SF{sf} {name}", sf, snr4, 0))
    # RSSI, under a comfortable SNR at SF8: it alone decides.
    for name, rssi in [
        ("RSSI strong", -60),
        ("RSSI at good", GOOD_RSSI_DBM),
        ("RSSI just under good", GOOD_RSSI_DBM - 1),
        ("RSSI at fair", FAIR_RSSI_DBM),
        ("RSSI just under fair", FAIR_RSSI_DBM - 1),
        ("RSSI at the floor", -128),
    ]:
        out.append((name, 8, 40, rssi))
    # The worse of the two.
    out.append(("weak SNR, strong RSSI", 8, -36, -80))
    out.append(("fair SNR, weak RSSI", 8, -16, -127))
    out.append(("good SNR, fair RSSI", 12, -40, -120))
    out.append(("an RSSI of 0 is not measured", 8, 40, 0))
    out.append(("an RSSI of 0 under a bad SNR", 7, -30, 0))
    return [(n, sf, s, r, rating(sf, s, r)) for n, sf, s, r in out]


def main():
    print("# A node's signal rating (protocol.md §16.1). Generated by signal.py: do not edit.")
    for name, sf, snr4, rssi, r in vectors():
        print()
        print("[[rating]]")
        print(f'name = "{name}"')
        print(f"sf = {sf}")
        print(f"snr4 = {snr4}")
        print(f"rssi = {rssi}")
        print(f'rating = "{r}"')


if __name__ == "__main__":
    main()
